@Test
public void builder() {
    {
        // empty
        try {
            PlcReadRequest.builder().build();
            fail("An empty builder should not be allowed to build a request");
        } catch (IllegalStateException e) {
            // expected
        }
    }
    {
        // one item
        PlcReadRequest.builder().addItem(String.class, dummyAddress).build();
    }
    {
        // one item sized
        PlcReadRequest.builder().addItem(String.class, dummyAddress, 13).build();
    }
    {
        // one item prebuild
        PlcReadRequest.builder().addItem(new ReadRequestItem<>(String.class, dummyAddress)).build();
    }
    {
        // two different item
        PlcReadRequest.builder().addItem(String.class, dummyAddress).addItem(Byte.class, dummyAddress).build();
    }
    {
        // two different item typeSafe
        try {
            PlcReadRequest.builder().addItem(String.class, dummyAddress).addItem(Byte.class, dummyAddress).build(String.class);
            fail("Should not succeed in building with mixed types.");
        } catch (IllegalStateException e) {
            // expected
        }
    }
    {
        // two different item typeSafe
        try {
            PlcReadRequest.builder().addItem(String.class, dummyAddress).addItem(Byte.class, dummyAddress).build(Byte.class);
            fail("Should not succeed in building with mismatch of types.");
        } catch (ClassCastException e) {
            // expected
        }
    }
    {
        // two equal item typeSafe
        PlcReadRequest.builder().addItem(Byte.class, dummyAddress).addItem(Byte.class, dummyAddress).build(Byte.class);
    }
}

