@Test
public void getPayloadLengthFromParameterTest() {
    // One bit is transferred inside one byte (4 byte header and one payload)
    assertThat(S7SizeHelper.getPayloadLength(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BIT, (short) 1, (short) 0, (short) 0, (byte) 0)), is((short) 5));
    assertThat(S7SizeHelper.getPayloadLength(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BYTE, (short) 1, (short) 0, (short) 0, (byte) 0)), is((short) 5));
    assertThat(S7SizeHelper.getPayloadLength(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.BYTE, (short) 42, (short) 0, (short) 0, (byte) 0)), is((short) 46));
    assertThat(S7SizeHelper.getPayloadLength(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.DWORD, (short) 1, (short) 0, (short) 0, (byte) 0)), is((short) 8));
    assertThat(S7SizeHelper.getPayloadLength(new S7AnyVarParameterItem(SpecificationType.VARIABLE_SPECIFICATION, MemoryArea.DATA_BLOCKS, TransportSize.DWORD, (short) 42, (short) 0, (short) 0, (byte) 0)), is((short) 172));
}

@Test
public void getPayloadLengthFromPayloadTest() {
    assertThat(S7SizeHelper.getPayloadLength(new VarPayloadItem(DataTransportErrorCode.OK, DataTransportSize.BIT, new byte[] { (byte) 0x01 })), is((short) 5));
    assertThat(S7SizeHelper.getPayloadLength(new VarPayloadItem(DataTransportErrorCode.OK, DataTransportSize.BYTE_WORD_DWORD, new byte[] { (byte) 0x01 })), is((short) 5));
    assertThat(S7SizeHelper.getPayloadLength(new VarPayloadItem(DataTransportErrorCode.OK, DataTransportSize.BYTE_WORD_DWORD, new byte[] { (byte) 0x01, (byte) 0x02, (byte) 0x03, (byte) 0x04, (byte) 0x05 })), is((short) 9));
    assertThat(S7SizeHelper.getPayloadLength(new VarPayloadItem(DataTransportErrorCode.OK, DataTransportSize.REAL, new byte[] { (byte) 0x01, (byte) 0x02, (byte) 0x03, (byte) 0x04 })), is((short) 8));
    assertThat(S7SizeHelper.getPayloadLength(new VarPayloadItem(DataTransportErrorCode.OK, DataTransportSize.REAL, new byte[] { (byte) 0x01, (byte) 0x02, (byte) 0x03, (byte) 0x04, (byte) 0x01, (byte) 0x02, (byte) 0x03, (byte) 0x04, (byte) 0x01, (byte) 0x02, (byte) 0x03, (byte) 0x04, (byte) 0x01, (byte) 0x02, (byte) 0x03, (byte) 0x04 })), is((short) 20));
}

